-- (10 Okt 2026) Pembagian awal Sub SLS identifikasi ke PML (permintaan user): 33 nagari terdampak (hasil gate identifikasi nagari) = 202 SLS / 621 Sub SLS.
-- Per SLS utuh -> 1 PML pelaksana (terdekat, garis lurus) + 1 PML pendamping; batas beban pelaksana 27-35 Sub SLS dan 3.900-5.300 KK.
-- PML tanpa koordinat memakai titik rata-rata PML kecamatannya (Yeni siswanti, Hariston, Ardial Jaraf = rata-rata PML Kubung; Ilham = titik Irawita);
-- Adriyanto belum punya lokasi sama sekali sehingga jaraknya netral (jarak_km dikosongkan) dan ia menyerap pembagian untuk menyeimbangkan beban.
insert into public.bencana_identifikasi_alokasi (idsls, iddesa, pml_pelaksana_id, pml_pendamping_id, jarak_km, catatan)
select v.idsls, left(v.idsls,10), v.pel, v.pen, case when v.pel = 5 then null else v.jarak end, 'Pembagian awal 10 Okt 2026'
